const intakeQueue = `-- name: IntakeQueue :many
SELECT r.id,r.statement,r.language_tag,r.publication_preference,r.intake_metadata,r.received_at,ir.version
FROM ops.report r JOIN ops.intake_review ir ON ir.report_id=r.id WHERE ir.state='PENDING' ORDER BY r.received_at LIMIT 100
`

type IntakeQueueRow struct {
	ID                    uuid.UUID          `json:"id"`
	Statement             string             `json:"statement"`
	LanguageTag           string             `json:"language_tag"`
	PublicationPreference string             `json:"publication_preference"`
	IntakeMetadata        []byte             `json:"intake_metadata"`
	ReceivedAt            pgtype.Timestamptz `json:"received_at"`
	Version               int64              `json:"version"`
}

func (q *Queries) IntakeQueue(ctx context.Context) ([]IntakeQueueRow, error) {
	rows, err := q.db.Query(ctx, intakeQueue)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []IntakeQueueRow{}
	for rows.Next() {
		var i IntakeQueueRow
		if err := rows.Scan(
			&i.ID,
			&i.Statement,
			&i.LanguageTag,
			&i.PublicationPreference,
			&i.IntakeMetadata,
			&i.ReceivedAt,
			&i.Version,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

